  let expense = 0;
  const byCategory = {};
  for (const it of items) {
    if (range) {
      if (range.from && it.date < range.from) continue;
      if (range.to && it.date > range.to) continue;
    }
    if (it.amount > 0) income += it.amount;
    else if (it.amount < 0) expense += -it.amount;
