const COLUMNS = ['date', 'description', 'amount', 'category'];

function parseRows(text) {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  let i = 0;
  const endRow = () => {
    row.push(field);
    field = '';
    rows.push(row);
    row = [];
  };
  while (i < text.length) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        quoted = false;
      } else {
        field += c;
      }
    } else if (c === '"') {
      quoted = true;
    } else if (c === ',') {
      row.push(field);
      field = '';
    } else if (c === '\r') {
      if (text[i + 1] === '\n') i++;
      endRow();
    } else if (c === '\n') {
      endRow();
    } else {
      field += c;
    }
    i++;
  }
  if (field !== '' || row.length > 0) endRow();
  return rows.filter((r) => !(r.length === 1 && r[0].trim() === ''));
}

export function parseCSV(text) {
  text = String(text ?? '').replace(/^﻿/, '');
  const rows = parseRows(text);
  let order = COLUMNS.map((_, i) => i);
  if (rows.length && rows[0][0].trim().toLowerCase() === 'date') {
    const header = rows.shift().map((h) => h.trim().toLowerCase());
    if (COLUMNS.every((c) => header.includes(c))) order = COLUMNS.map((c) => header.indexOf(c));
  }
  return rows.map((r) => {
    const get = (k) => r[order[k]] ?? '';
    return {
      date: get(0).trim(),
      description: get(1),
      amount: Number(get(2).trim()),
      category: get(3),
    };
  });
}

function quote(value) {
  const s = String(value ?? '');
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

export function toCSV(items) {
  const lines = [COLUMNS.join(',')];
  for (const it of items) {
    lines.push(COLUMNS.map((c) => quote(it[c])).join(','));
  }
  return lines.join('\n');
}
EOF
cat > summary.js <<'EOF'
export function summarize(items, range) {
  let income = 0;
  let expense = 0;
  const byCategory = {};
  for (const it of items) {
    if (range) {
      if (range.from && it.date < range.from) continue;
      if (range.to && it.date > range.to) continue;
    }
    if (it.amount > 0) income += it.amount;
    else if (it.amount < 0) expense += -it.amount;
    byCategory[it.category] = (byCategory[it.category] ?? 0) + it.amount;
  }
  return { income, expense, balance: income - expense, byCategory };
}
EOF
cat > recurring.js <<'EOF'
const pad = (n, w = 2) => String(n).padStart(w, '0');

export function expandRecurring(rule, until) {
  const { every, ...base } = rule;
  const [y, m, d] = rule.date.split('-').map(Number);
  const out = [];
  for (let n = 0; n < 100000; n++) {
    let date;
    if (every === 'week') {
      date = new Date(Date.UTC(y, m - 1, d + 7 * n)).toISOString().slice(0, 10);
    } else if (every === 'month') {
      const total = m - 1 + n;
      const yy = y + Math.floor(total / 12);
      const mm = total % 12;
      const last = new Date(Date.UTC(yy, mm + 1, 0)).getUTCDate();
      date = `${pad(yy, 4)}-${pad(mm + 1)}-${pad(Math.min(d, last))}`;
    } else {
      if (n === 0 && rule.date <= until) out.push({ ...base });
      break;
    }
    if (date > until) break;
    out.push({ ...base, date });
  }
  return out;
}
EOF
